input.command:
cd "C:/Users/Gabriel/barte-hackathon/instructions/Tarvo_Data_Pack_set2026" && python -I - <<'EOF'
import csv,collections
rows=list(csv.DictReader(open('01_orbe_relatorio_comissoes_set2026.csv',encoding='utf-8-sig',errors='replace'),delimiter=';'))
print(len(rows))
for k in ['tipo_lancamento','modalidade','qtd_parcelas','bandeira']:
    print(k,collections.Counter(r[k] for r in rows))
print(collections.Counter((r['cod_estabelecimento'],r['nome_estabelecimento']) for r in rows).most_common(60))
for t in ['ESTORNO','ANTECIPACAO','REVERSAO']:
    pass
seen=set()
for r in rows:
    if r['tipo_lancamento'] not in seen and r['tipo_lancamento']!='VENDA':
        seen.add(r['tipo_lancamento']);
for t in set(r['tipo_lancamento'] for r in rows):
    print('--',t)
    for r in [x for x in rows if x['tipo_lancamento']==t][:3]: print(r)
ids=collections.Counter(r['id_transacao'] for r in rows); print('dup ids',[i for i,c in ids.items() if c>1][:10])
print(collections.Counter(r['data_movimento'][3:] for r in rows))
EOF

